      .help-text,
      .error-text {
        margin: 0;
        font-size: 0.94rem;
      }

      .help-text {
        color: var(--color-muted);
      }

      .error-text {
        color: var(--color-error);
        font-weight: 700;
      }

      .error-text[hidden] {
        display: none;
      }

      .actions {
        display: grid;
        gap: 1rem;
        margin-top: 0.5rem;
      }

      button {
        min-height: 3.35rem;
        border: 0;
        border-radius: var(--radius-md);
        background: var(--color-primary);
        color: #ffffff;
        cursor: pointer;
        font: inherit;
        font-weight: 800;
        transition:
          background-color 160ms ease,
          transform 160ms ease;
      }

      button:hover {
        background: var(--color-primary-hover);
      }

      button:focus {
        outline: 3px solid transparent;
        box-shadow:
          0 0 0 3px var(--color-surface),
          0 0 0 7px var(--color-focus);
      }

      button:active {
        transform: translateY(1px);
      }

      .status-message {
        min-height: 1.5rem;
        margin: 0;
        color: var(--color-success);
        font-weight: 750;
      }

      @media (max-width: 760px) {
        .page-shell {
          display: block;
          padding: 1rem;
        }

        .support-card {
          grid-template-columns: 1fr;
        }

        .support-intro,
        .form-panel {
          padding: 1.5rem;
