        --color-border: #9aa9bc;
        --color-border-strong: #66758a;
        --color-primary: #1658d3;
        --color-primary-hover: #0f45aa;
        --color-focus: #8b3ffc;
        --color-error: #b42318;
        --color-success: #1a6b3a;
        --shadow-card: 0 24px 70px #d9e1ef;
        --radius-lg: 28px;
        --radius-md: 16px;
      }

      * {
        box-sizing: border-box;
      }

      html {
        scroll-behavior: smooth;
      }

      body {
        margin: 0;
        min-width: 320px;
        min-height: 100vh;
        background:
          radial-gradient(circle at top left, #e4edff 0, transparent 34rem),
          linear-gradient(135deg, var(--color-page), #eef3f9);
        color: var(--color-text);
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        line-height: 1.5;
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 10;
        transform: translateY(-150%);
        border-radius: 999px;
        background: var(--color-text);
        color: var(--color-surface);
        padding: 0.75rem 1rem;
        font-weight: 700;
      }

      .skip-link:focus {
        transform: translateY(0);
        outline: 3px solid transparent;
        box-shadow: 0 0 0 4px var(--color-focus);
      }

      .page-shell {
        display: grid;
        place-items: center;
        min-height: 100vh;
        padding: 2rem;
      }

      main {
        width: min(100%, 68rem);
      }

      .support-card {
        display: grid;
        grid-template-columns: minmax(0, 0.92fr) minmax(18rem, 1.08fr);
        overflow: hidden;
        border: 1px solid #dde5f1;
        border-radius: var(--radius-lg);
        background: var(--color-surface);
        box-shadow: var(--shadow-card);
      }

      .support-intro {
        display: flex;
        flex-direction: column;
        justify-content: space-between;
        gap: 3rem;
        background: linear-gradient(160deg, #172033, #243b66);
        color: #ffffff;
        padding: clamp(2rem, 5vw, 4rem);
      }

      .eyebrow {
        margin: 0 0 1rem;
        color: #c7d7ff;
        font-size: 0.82rem;
        font-weight: 800;
        letter-spacing: 0.12em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        max-width: 11ch;
        font-size: clamp(2.5rem, 7vw, 5rem);
        line-height: 0.95;
        letter-spacing: -0.07em;
      }

      .intro-copy {
        margin: 1.5rem 0 0;
        max-width: 34rem;
        color: #e3ebff;
        font-size: 1.08rem;
      }

      .response-note {
        margin: 0;
        border-left: 4px solid #9ab7ff;
        padding-left: 1rem;
        color: #edf3ff;
      }

      .form-panel {
        padding: clamp(1.5rem, 5vw, 4rem);
      }

      .form-heading {
        margin: 0 0 0.35rem;
        font-size: clamp(1.5rem, 3vw, 2rem);
        line-height: 1.2;
        letter-spacing: -0.03em;
      }

      .form-subtitle {
        margin: 0 0 2rem;
        color: var(--color-muted);
      }

      form {
        display: grid;
        gap: 1.15rem;
      }

      .form-field {
        display: grid;
        gap: 0.45rem;
      }

      label {
        color: var(--color-text);
        font-weight: 750;
      }

      .field-meta {
        color: var(--color-muted);
        font-size: 0.92rem;
        font-weight: 650;
      }

      input {
        width: 100%;
        min-height: 3.35rem;
        border: 1.5px solid var(--color-border);
        border-radius: var(--radius-md);
        background: #fbfdff;
        color: var(--color-text);
        padding: 0.9rem 1rem;
        font: inherit;
        transition:
          border-color 160ms ease,
          box-shadow 160ms ease,
          background-color 160ms ease;
      }

      input:hover {
        border-color: var(--color-border-strong);
      }

      input:focus {
        outline: 3px solid transparent;
        border-color: var(--color-focus);
        background: var(--color-surface);
        box-shadow: 0 0 0 4px #e6dcff;
      }

      input[aria-invalid="true"] {
        border-color: var(--color-error);
      }

      .help-text,
      .error-text {
        margin: 0;
        font-size: 0.94rem;
      }

      .help-text {
        color: var(--color-muted);
      }

      .error-text {
        color: var(--color-error);
        font-weight: 700;
      }

      .error-text[hidden] {
        display: none;
      }

      .actions {
        display: grid;
        gap: 1rem;
        margin-top: 0.5rem;
      }

      button {
        min-height: 3.35rem;
        border: 0;
        border-radius: var(--radius-md);
        background: var(--color-primary);
        color: #ffffff;
        cursor: pointer;
        font: inherit;
        font-weight: 800;
        transition:
          background-color 160ms ease,
          transform 160ms ease;
      }

      button:hover {
        background: var(--color-primary-hover);
      }

      button:focus {
        outline: 3px solid transparent;
        box-shadow:
          0 0 0 3px var(--color-surface),
          0 0 0 7px var(--color-focus);
      }

      button:active {
        transform: translateY(1px);
      }

      .status-message {
        min-height: 1.5rem;
        margin: 0;
        color: var(--color-success);
        font-weight: 750;
      }

      @media (max-width: 760px) {
        .page-shell {
          display: block;
          padding: 1rem;
        }

        .support-card {
          grid-template-columns: 1fr;
        }

        .support-intro,
        .form-panel {
          padding: 1.5rem;
        }

        h1 {
          max-width: 12ch;
        }
      }

      @media (max-width: 380px) {
        .page-shell {
          padding: 0.5rem;
        }

        .support-card {
          border-radius: 20px;
        }

        .support-intro,
        .form-panel {
          padding: 1.15rem;
        }
      }

      @media (prefers-reduced-motion: reduce) {
        html {
          scroll-behavior: auto;
        }

        *,
        *::before,
        *::after {
          transition-duration: 0.01ms !important;
          animation-duration: 0.01ms !important;
          animation-iteration-count: 1 !important;
