        font-size: 1.08rem;
      }

      .response-note {
        margin: 0;
        border-left: 4px solid #9ab7ff;
        padding-left: 1rem;
        color: #edf3ff;
      }

      .form-panel {
        padding: clamp(1.5rem, 5vw, 4rem);
      }

      .form-heading {
        margin: 0 0 0.35rem;
        font-size: clamp(1.5rem, 3vw, 2rem);
        line-height: 1.2;
