      }

      .actions {
        display: grid;
        gap: 1rem;
        margin-top: 0.5rem;
      }

      button {
        min-height: 3.35rem;
        border: 0;
        border-radius: var(--radius-md);
        background: var(--color-primary);
        color: #ffffff;
        cursor: pointer;
        font: inherit;
        font-weight: 800;
        transition:
