  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div class="page-shell">
      <main id="main-content">
        <section class="support-card" aria-labelledby="support-title" data-component="ContactForm">
          <div class="support-intro">
            <div>
              <p class="eyebrow">Support desk</p>
              <h1 id="support-title">Contact support</h1>
              <p class="intro-copy">
                Tell us how to reach you and our team will follow up with the
                right specialist.
              </p>
            </div>
            <p class="response-note">
              We usually reply within one business day.
            </p>
          </div>

          <div class="form-panel">
            <h2 class="form-heading">How can we reach you?</h2>
            <p class="form-subtitle">
              Full name and email address are required. Phone number is optional.
            </p>

            <form id="support-form" novalidate>
              <div class="form-field" data-component="Field">
                <label for="full-name">
                  Full name
                  <span class="field-meta">(required)</span>
                </label>
                <input
                  id="full-name"
                  name="fullName"
                  type="text"
                  autocomplete="name"
                  required
                  aria-required="true"
                  aria-describedby="full-name-error"
                />
                <p class="error-text" id="full-name-error" hidden></p>
              </div>

              <div class="form-field" data-component="Field">
                <label for="email-address">
                  Email address
                  <span class="field-meta">(required)</span>
                </label>
                <input
                  id="email-address"
                  name="email"
                  type="email"
                  autocomplete="email"
                  required
                  aria-required="true"
                  aria-describedby="email-address-error"
                />
                <p class="error-text" id="email-address-error" hidden></p>
              </div>

              <div class="form-field" data-component="Field">
                <label for="phone-number">
                  Phone number
                  <span class="field-meta">(optional)</span>
                </label>
                <input
                  id="phone-number"
                  name="phone"
                  type="tel"
                  autocomplete="tel"
                  pattern="\(?[0-9]{3}\)?[-. ]?[0-9]{3}[-. ]?[0-9]{4}"
                  aria-describedby="phone-number-help phone-number-error"
                />
                <p class="help-text" id="phone-number-help">
                  Use 10 digits, such as (555) 123-4567.
                </p>
                <p class="error-text" id="phone-number-error" hidden></p>
              </div>

              <div class="actions">
                <button type="submit">Submit support request</button>
                <p class="status-message" id="form-status" aria-live="polite"></p>
              </div>
            </form>
          </div>
        </section>
      </main>
    </div>

    <script>
      const fields = [
        {
          id: "full-name",
          name: "fullName",
          label: "Full name",
          autocomplete: "name",
          required: true,
          type: "text",
          error: "Enter your full name."
        },
        {
          id: "email-address",
          name: "email",
          label: "Email address",
          autocomplete: "email",
          required: true,
          type: "email",
          error: "Enter a valid email address."
        },
        {
          id: "phone-number",
          name: "phone",
          label: "Phone number",
          autocomplete: "tel",
          required: false,
          type: "tel",
          helper: "Use 10 digits, such as (555) 123-4567.",
          pattern: "\\(?[0-9]{3}\\)?[-. ]?[0-9]{3}[-. ]?[0-9]{4}",
          error: "Enter a 10-digit phone number, such as (555) 123-4567."
        }
      ];

      const form = document.querySelector("#support-form");
      const statusMessage = document.querySelector("#form-status");
      let hasSubmitted = false;

      function getErrorMessage(field, input) {
        const value = input.value.trim();

        if (field.required && value === "") {
          return field.error;
        }

        if (field.type === "email" && value !== "" && !input.validity.valid) {
          return field.error;
        }

        if (field.name === "phone" && value !== "" && !input.validity.valid) {
          return field.error;
        }

        return "";
      }

      function validateField(field) {
        const input = document.querySelector(`#${field.id}`);
        const errorText = document.querySelector(`#${field.id}-error`);
        const errorMessage = getErrorMessage(field, input);

        if (errorMessage) {
          input.setAttribute("aria-invalid", "true");
          errorText.textContent = errorMessage;
          errorText.hidden = false;
        } else {
          input.removeAttribute("aria-invalid");
          errorText.textContent = "";
          errorText.hidden = true;
        }

        return !errorMessage;
      }

      function clearFieldError(field) {
        const input = document.querySelector(`#${field.id}`);
        const errorText = document.querySelector(`#${field.id}-error`);

        input.removeAttribute("aria-invalid");
        errorText.textContent = "";
        errorText.hidden = true;
      }

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        hasSubmitted = true;

        const invalidFields = fields.filter((field) => !validateField(field));
        const firstInvalidField = invalidFields[0];

        if (firstInvalidField) {
          statusMessage.textContent = "";
          document.querySelector(`#${firstInvalidField.id}`).focus();
          return;
        }

        statusMessage.textContent =
          "Thanks. Your support request contact details are ready to send.";
        form.reset();
        fields.forEach(clearFieldError);
      });

      fields.forEach((field) => {
        document.querySelector(`#${field.id}`).addEventListener("input", () => {
          if (hasSubmitted) {
            validateField(field);
          }
          statusMessage.textContent = "";
        });
      });
    </script>
  </body>
</html>
